<?php
require __DIR__.'/bootstrap.php';require_admin();require __DIR__.'/movidesk.php';require __DIR__.'/portal-data.php';
$contractId=max(1,(int)($_GET['id']??0));$month=preg_match('/^\d{4}-\d{2}$/',$_GET['month']??'')?$_GET['month']:date('Y-m');
$st=$pdo->prepare("SELECT ct.*,c.name company FROM contracts ct JOIN companies c ON c.id=ct.company_id WHERE ct.id=? AND ct.status='active' AND c.status='active'");$st->execute([$contractId]);$contract=$st->fetch();if(!$contract){http_response_code(404);exit('Contrato não encontrado.');}
$usage=['raw'=>[],'appointments'=>[],'consumed'=>0.0];$error='';$periodClosed=false;try{$usage=portal_consumption((string)$contract['name'],$month);}catch(Throwable $e){error_log('Newsiga detalhe contrato '.$contract['name'].': '.$e->getMessage());$error='Não foi possível carregar os dados deste contrato agora.';}
$periodClosed=portal_period_is_closed($usage['raw']);$contracted=(float)($usage['raw']['contractedHours']??$contract['monthly_hours']);$consumed=(float)$usage['consumed'];$available=max(0,$contracted-$consumed);$extra=max(0,$consumed-$contracted);$percent=$contracted>0?($consumed/$contracted)*100:0;$tickets=portal_group_tickets($usage['appointments']);$workTypes=[];$responsibles=[];foreach($tickets as $ticket)foreach(($ticket['hours_by_type']??[])as $type=>$hours)$workTypes[$type]=($workTypes[$type]??0)+(float)$hours;foreach($usage['appointments'] as $appointment){$responsible=(string)($appointment['createdBy']['businessName']??'Não identificado');$responsibles[$responsible]=($responsibles[$responsible]??0)+portal_entry_hours($appointment);}arsort($workTypes);arsort($responsibles);
function contract_detail_date(string $date):string{$timestamp=strtotime($date);return$timestamp?date('d/m/Y',$timestamp):$date;}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=e($contract['company'])?> | Acompanhamento</title><link rel="stylesheet" href="assets/style.css?v=7.5.3"><style>.detail-wrap{width:min(1100px,calc(100% - 32px));margin:38px auto}.detail-head{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:24px}.detail-head h1{margin:6px 0}.detail-head p{margin:0}.period-form{display:flex;align-items:end;gap:8px;margin:0}.period-form label{min-width:180px}.period-form button{height:48px}.detail-actions{display:flex;align-items:end;gap:10px;flex-wrap:wrap}.print-btn{height:48px}.back{display:inline-flex;margin-bottom:20px;color:#176c58;text-decoration:none;font-size:12px;font-weight:800}.detail-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.detail-metrics article,.detail-panel{background:#fff;border:1px solid #d9dfda;padding:22px}.detail-metrics small{display:block;color:#71817b;font-size:9px;font-weight:800;letter-spacing:.09em;margin-bottom:12px}.detail-metrics strong{font-size:24px}.detail-metrics .danger strong{color:#a53d32}.detail-progress{height:9px;background:#e1e8e4;margin:12px 0 4px}.detail-progress span{display:block;height:100%;background:#35a77d}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}.detail-panel h2{margin:0 0 18px}.breakdown{display:grid;gap:11px}.breakdown div{display:flex;justify-content:space-between;gap:15px;padding-bottom:10px;border-bottom:1px solid #e1e6e2}.breakdown div:last-child{border:0}.detail-table{overflow:auto}.detail-table table{min-width:760px}.data-state{display:inline-flex;margin-bottom:16px;padding:6px 9px;background:#fff6dc;color:#705711;font-size:10px;font-weight:800}.data-state.closed{background:#e4f4de;color:#28652d}.financial-note{padding:12px 15px;background:#fff6dc;border-left:3px solid #d5a11f;color:#6e5310;font-size:12px;margin-bottom:16px}@media(max-width:760px){.detail-head,.detail-actions{display:grid}.detail-metrics{grid-template-columns:1fr 1fr}.detail-grid{grid-template-columns:1fr}}@media print{body{background:#fff}header.top{display:none}.back{display:none}.period-form,.print-btn{display:none}.detail-wrap{width:100%;margin:0;padding:15mm}.detail-metrics,.detail-grid{-webkit-print-color-adjust:exact;print-color-adjust:exact}@page{size:A4;margin:0}}</style></head><body><header class="top"><a class="brand" href="<?=url('dashboard.php')?>">newsiga</a><nav><a href="<?=url('dashboard.php')?>">Painel</a><a href="<?=url('admin/')?>">Administração</a><a href="<?=url('logout.php')?>">Sair</a></nav></header><main class="detail-wrap"><a class="back" href="<?=url('dashboard.php?month='.urlencode($month))?>">← Voltar ao Painel</a><div class="detail-head"><div><p class="kicker">DETALHAMENTO DO CONTRATO</p><h1><?=e($contract['company'])?></h1><p class="muted"><?=e($contract['name'])?></p></div><div class="detail-actions"><form class="period-form" method="get"><input type="hidden" name="id" value="<?=$contractId?>"><label>Competência<input name="month" type="month" value="<?=e($month)?>"></label><button class="button">Consultar</button></form><button type="button" class="button print-btn" onclick="window.print()">Imprimir / salvar PDF</button></div></div><?php if($error):?><p class="error"><?=e($error)?></p><?php else:?><p class="data-state <?=$periodClosed?'closed':''?>"><?=$periodClosed?'Fechamento oficial':'Prévia do período'?></p><div class="financial-note">Os valores financeiros não são exibidos nesta tela enquanto as regras de cobrança estão em validação.</div><section class="detail-metrics"><article><small>HORAS CONTRATADAS</small><strong><?=portal_duration($contracted)?></strong></article><article><small>HORAS CONSUMIDAS</small><strong><?=portal_duration($consumed)?></strong></article><article class="<?=$extra>0?'danger':''?>"><small><?=$extra>0?'HORAS EXCEDENTES':'HORAS DISPONÍVEIS'?></small><strong><?=portal_duration($extra>0?$extra:$available)?></strong></article><article><small>UTILIZAÇÃO</small><strong><?=number_format($percent,0,',','.')?>%</strong><div class="detail-progress"><span style="width:<?=min(100,$percent)?>%"></span></div></article></section><div class="detail-grid"><section class="detail-panel"><h2>Consumo por tipo de hora</h2><div class="breakdown"><?php foreach($workTypes as $type=>$hours):?><div><span><?=e($type)?></span><strong><?=portal_duration($hours)?></strong></div><?php endforeach;?><?php if(!$workTypes):?><p class="muted">Nenhum tipo de hora encontrado.</p><?php endif;?></div></section><section class="detail-panel"><h2>Consumo por responsável</h2><div class="breakdown"><?php foreach($responsibles as $responsible=>$hours):?><div><span><?=e($responsible)?></span><strong><?=portal_duration($hours)?></strong></div><?php endforeach;?><?php if(!$responsibles):?><p class="muted">Nenhum responsável encontrado.</p><?php endif;?></div></section></div><section class="detail-panel detail-table"><h2>Chamados da competência</h2><table><thead><tr><th>Ticket</th><th>Data</th><th>Atividade</th><th>Tipo de hora</th><th>Responsável</th><th>Tempo</th></tr></thead><tbody><?php foreach($tickets as $ticket):?><tr><td><strong>#<?=e($ticket['number'])?></strong></td><td><?=e(contract_detail_date((string)$ticket['date']))?></td><td><?=e($ticket['activity'])?></td><td><?=e(implode(', ',array_keys($ticket['work_types'])))?></td><td><?=e(implode(', ',array_keys($ticket['responsibles'])))?></td><td><strong><?=portal_duration((float)$ticket['hours'])?></strong></td></tr><?php endforeach;?><?php if(!$tickets):?><tr><td colspan="6">Nenhum atendimento encontrado nesta competência.</td></tr><?php endif;?></tbody></table></section><?php endif;?></main></body></html>
